/** A snapshot of stock is not a promise of current availability. */
export function stockLabel(shop, now = Date.now()) {
  const count = shop?.stockCount;
  if (!Number.isSafeInteger(count) || count < 0) return "Unknown stock";
  const observed = Date.parse(shop.lastStockSeenAt);
  const stale = !Number.isFinite(observed) || now - observed > 24 * 60 * 60 * 1000;
  const label = count === 0 ? "Out of stock when scanned" : `${count.toLocaleString()} last observed`;
  return stale ? `${label} (stale)` : label;
}

export function stockTimestamp(shop) {
  const observed = Date.parse(shop?.lastStockSeenAt);
  return Number.isFinite(observed)
    ? `Stock observed ${new Date(observed).toLocaleString()}; availability may have changed`
    : "Stock observation time unknown";
}

/** Do not pool stock from distinct signs, prices, variants or floors into one listing. */
export function distinctShopRows(rows) {
  const shops = new Map();
  rows.forEach((row, index) => {
    const located = typeof row.serverKey === "string" && typeof row.dimensionKey === "string"
      && [row.x, row.y, row.z].every(Number.isInteger);
    const key = located ? JSON.stringify([row.serverKey, row.dimensionKey, row.x, row.y, row.z])
      : `unlocated-${index}`;
    const previous = shops.get(key);
    if (!previous || (Date.parse(row.updatedAt) || 0) >= (Date.parse(previous.updatedAt) || 0)) {
      shops.set(key, { ...row, count: 1 });
    }
  });
  return [...shops.values()];
}
